import React from "react";
import "./MyEvents.css";
import headerImage from "../../../assets/MyEventsHeader.png"; // correct relative import

const MyEvents = () => {
  const events = [
    { id: 1, name: "TED talk", date: "2025-10-20", location: "Hall building" },
    { id: 2, name: "Get together", date: "2025-11-05", location: "ER building" }
  ];

  return (
    <div className="my-events-container">
      <div className="header-image">
        <h1>My Events</h1>
      </div>

      <div className="events-list-section">
        {events.length === 0 ? (
          <p>You haven’t purchased any events yet.</p>
        ) : (
          <ul className="event-list">
            {events.map((event) => (
              <li key={event.id} className="event-item">
                <h3>{event.name}</h3>
                <p>Date: {event.date}</p>
                <p>Location: {event.location}</p>
              </li>
            ))}
          </ul>
        )}
      </div>
  </div>
  );
};

export default MyEvents;
